styles:
@font-face{ font-family:"Manrope";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/manrope/v20/xn7gYHE41ni1AdIRggexSg.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap; }
@font-face{ font-family:"Space Grotesk";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4Cw.woff2") format("woff2");font-weight:300 700;font-style:normal;font-display:swap; }

.dgs-seo-ads-page,
.dgs-seo-ads-page * {
  box-sizing: border-box !important;
}

.dgs-seo-ads-page {
  --dgs-bg: #fbfaf7;
  --dgs-bg-soft: #f4f1ec;
  --dgs-card: #ffffff;
  --dgs-text: #14111f;
  --dgs-muted: #5e5a66;
  --dgs-soft: #85808f;
  --dgs-line: rgba(20,17,31,0.12);
  --dgs-line-strong: rgba(20,17,31,0.2);
  --dgs-orange: #e8612a;
  --dgs-rose: #c43f7a;
  --dgs-violet: #6247b0;
  --dgs-green: #1f9d62;
  --dgs-gradient: linear-gradient(135deg, #e8612a 0%, #c43f7a 50%, #6247b0 100%);
  --dgs-radius-sm: 12px;
  --dgs-radius: 22px;
  --dgs-radius-lg: 30px;
  --dgs-radius-xl: 42px;
  --dgs-shadow: 0 24px 70px rgba(20,17,31,0.08);
  --dgs-shadow-strong: 0 34px 90px rgba(20,17,31,0.14);
  font-family: "Manrope", Arial, sans-serif !important;
  background: var(--dgs-bg) !important;
  color: var(--dgs-text) !important;
  overflow: hidden !important;
  line-height: 1.65 !important;
  width: 100vw !important;
  max-width: 100vw !important;
  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;
}


body:has(.dgs-seo-ads-page) .site-main,
body:has(.dgs-seo-ads-page) .entry-content,
body:has(.dgs-seo-ads-page) .elementor,
body:has(.dgs-seo-ads-page) .elementor-section-wrap,
body:has(.dgs-seo-ads-page) .elementor-widget-container {
  max-width: none !important;
  width: 100% !important;
}

.dgs-seo-ads-page a {
  color: inherit !important;
  text-decoration: none !important;
}

.dgs-seo-ads-page img {
  max-width: 100% !important;
  display: block !important;
}

.dgs-seo-wrap {
  width: min(1500px, calc(100% - 40px)) !important;
  margin: 0 auto !important;
  position: relative !important;
  z-index: 2 !important;
}

.dgs-grad-text {
  background: var(--dgs-gradient) !important;
  background-size: 220% 220% !important;
  -webkit-background-clip: text !important;
  background-clip: text !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
}

.dgs-eyebrow {
  display: inline-flex !important;
  align-items: center !important;
  gap: 9px !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  letter-spacing: 1.8px !important;
  text-transform: uppercase !important;
  color: var(--dgs-orange) !important;
  border: 1px solid rgba(232,97,42,0.24) !important;
  background: rgba(232,97,42,0.055) !important;
  padding: 8px 16px !important;
  border-radius: 999px !important;
  margin-bottom: 20px !important;
}

.dgs-eyebrow:before {
  content: "" !important;
  width: 7px !important;
  height: 7px !important;
  border-radius: 50% !important;
  background: var(--dgs-orange) !important;
  box-shadow: 0 0 10px rgba(232,97,42,0.52) !important;
}

.dgs-section {
  padding: 82px 0 !important;
  background: transparent !important;
  position: relative !important;
}

.dgs-section-soft {
  background: var(--dgs-bg-soft) !important;
}

.dgs-section-head {
  text-align: center !important;
  max-width: 860px !important;
  margin: 0 auto 46px !important;
}

.dgs-section-head h2 {
  font-family: "Manrope", Arial, sans-serif !important;
  font-size: clamp(34px, 4.5vw, 58px) !important;
  font-weight: 850 !important;
  line-height: 1.05 !important;
  letter-spacing: -0.055em !important;
  color: var(--dgs-text) !important;
  margin: 0 0 14px !important;
}

.dgs-section-head p {
  color: var(--dgs-muted) !important;
  font-size: 16.5px !important;
  line-height: 1.75 !important;
  margin: 0 !important;
}

.dgs-divider {
  width: 70px !important;
  height: 2px !important;
  border-radius: 999px !important;
  background: var(--dgs-gradient) !important;
  margin: 22px auto 0 !important;
}

.dgs-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 10px !important;
  min-height: 54px !important;
  padding: 15px 24px !important;
  border-radius: 999px !important;
  border: 1px solid transparent !important;
  font-family: "Manrope", Arial, sans-serif !important;
  font-size: 15px !important;
  font-weight: 850 !important;
  line-height: 1.2 !important;
  transition: 0.28s ease !important;
  cursor: pointer !important;
}

.dgs-btn-primary {
  background: var(--dgs-gradient) !important;
  background-image: var(--dgs-gradient) !important;
  color: #ffffff !important;
  box-shadow: 0 16px 42px rgba(196,63,122,0.26) !important;
}

.dgs-btn-primary:hover {
  color: #ffffff !important;
  transform: translateY(-3px) !important;
  box-shadow: 0 24px 60px rgba(196,63,122,0.36) !important;
}

.dgs-btn-ghost {
  color: var(--dgs-text) !important;
  background: #ffffff !important;
  background-image: none !important;
  border-color: var(--dgs-line) !important;
  box-shadow: 0 10px 34px rgba(20,17,31,0.06) !important;
}

.dgs-btn-ghost:hover {
  color: var(--dgs-orange) !important;
  border-color: rgba(232,97,42,0.46) !important;
  background: #ffffff !important;
  background-image: none !important;
  transform: translateY(-3px) !important;
}

.dgs-hero {
  padding: 54px 0 46px !important;
  background:
    radial-gradient(circle at 12% 14%, rgba(232,97,42,0.10), transparent 30%),
    radial-gradient(circle at 88% 5%, rgba(98,71,176,0.11), transparent 36%),
    linear-gradient(180deg, #ffffff 0%, var(--dgs-bg) 100%) !important;
}

.dgs-hero-grid {
  display: grid !important;
  grid-template-columns: minmax(0, 1.02fr) minmax(520px, 0.98fr) !important;
  gap: 48px !important;
  align-items: start !important;
}

.dgs-hero-copy {
  padding-top: 18px !important;
}

.dgs-hero h1 {
  font-family: "Manrope", Arial, sans-serif !important;
  font-size: clamp(38px, 4.15vw, 64px) !important;
  font-weight: 900 !important;
  line-height: 1.06 !important;
  letter-spacing: -0.055em !important;
  color: var(--dgs-text) !important;
  margin: 0 0 22px !important;
}

.dgs-hero-sub {
  color: var(--dgs-muted) !important;
  font-size: 17px !important;
  line-height: 1.75 !important;
  max-width: 720px !important;
  margin: 0 0 26px !important;
}

.dgs-hero-actions {
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 14px !important;
  margin: 0 0 28px !important;
}

.dgs-proof-row {
  display: grid !important;
  grid-template-columns: repeat(3, 1fr) !important;
  gap: 12px !important;
  max-width: 720px !important;
}

.dgs-proof-card {
  background: #ffffff !important;
  border: 1px solid var(--dgs-line) !important;
  border-radius: 18px !important;
  padding: 17px !important;
  box-shadow: 0 14px 38px rgba(20,17,31,0.055) !important;
}

.dgs-proof-card strong {
  display: block !important;
  color: var(--dgs-text) !important;
  font-size: 24px !important;
  line-height: 1.1 !important;
  margin-bottom: 6px !important;
}

.dgs-proof-card span {
  display: block !important;
  color: var(--dgs-muted) !important;
  font-size: 13px !important;
  line-height: 1.42 !important;
}

.dgs-hero-value-panel {
  margin-top: 18px !important;
  max-width: 760px !important;
  border: 1px solid rgba(20,17,31,0.10) !important;
  background: rgba(255,255,255,0.74) !important;
  backdrop-filter: blur(14px) !important;
  border-radius: 26px !important;
  padding: 22px !important;
  box-shadow: 0 18px 54px rgba(20,17,31,0.06) !important;
}

.dgs-hero-value-panel strong {
  display: block !important;
  color: var(--dgs-text) !important;
  font-size: 18px !important;
  font-weight: 950 !important;
  letter-spacing: -0.02em !important;
  margin-bottom: 14px !important;
}

.dgs-hero-value-grid {
  display: grid !important;
  grid-template-columns: repeat(2, 1fr) !important;
  gap: 10px !important;
}

.dgs-hero-value-item {
  display: grid !important;
  grid-template-columns: 24px 1fr !important;
  gap: 10px !important;
  align-items: start !important;
  padding: 12px !important;
  border: 1px solid rgba(20,17,31,0.08) !important;
  border-radius: 16px !important;
  background: #ffffff !important;
}

.dgs-hero-value-item b {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 24px !important;
  height: 24px !important;
  border-radius: 999px !important;
  background: rgba(232,97,42,0.10) !important;
  color: var(--dgs-orange) !important;
  font-size: 12px !important;
  font-weight: 950 !important;
}

.dgs-hero-value-item span {
  color: var(--dgs-muted) !important;
  font-size: 13px !important;
  line-height: 1.48 !important;
  display: block !important;
}

.dgs-hero-bottom-note {
  margin-top: 14px !important;
  color: var(--dgs-soft) !important;
  font-size: 12px !important;
  line-height: 1.55 !important;
}

.dgs-form-card {
  background: #ffffff !important;
  border: 1px solid var(--dgs-line) !important;
  border-radius: var(--dgs-radius-lg) !important;
  padding: 24px !important;
  box-shadow: var(--dgs-shadow-strong) !important;
  position: relative !important;
  z-index: 5 !important;
}

.dgs-form-card h2 {
  font-family: "Manrope", Arial, sans-serif !important;
  font-size: 30px !important;
  font-weight: 900 !important;
  letter-spacing: -0.04em !important;
  line-height: 1.08 !important;
  color: var(--dgs-text) !important;
  margin: 0 0 10px !important;
}

.dgs-form-card p {
  color: var(--dgs-muted) !important;
  font-size: 14px !important;
  line-height: 1.65 !important;
  margin: 0 0 18px !important;
}

.dgs-b2b-strip {
  border: 1px solid rgba(31,157,98,0.24) !important;
  background: rgba(31,157,98,0.065) !important;
  border-radius: 18px !important;
  padding: 13px 15px !important;
  margin-bottom: 14px !important;
}

.dgs-b2b-strip strong {
  display: block !important;
  color: var(--dgs-text) !important;
  font-size: 14px !important;
  margin-bottom: 5px !important;
}

.dgs-b2b-strip span {
  display: block !important;
  color: var(--dgs-muted) !important;
  font-size: 12px !important;
  line-height: 1.55 !important;
}

.dgs-form-slot {
  border-radius: 22px !important;
  border: 1px solid rgba(20,17,31,0.10) !important;
  background: #fbfaf7 !important;
  padding: 14px !important;
  min-height: 320px !important;
}

.dgs-form-note {
  margin-top: 14px !important;
  color: var(--dgs-soft) !important;
  font-size: 11px !important;
  line-height: 1.5 !important;
}


/* FLUENT FORMS HARD OVERRIDE FOR THIS LANDING PAGE */
.dgs-seo-ads-page .dgs-form-slot .fluentform,
.dgs-seo-ads-page .dgs-form-slot .frm-fluent-form,
.dgs-seo-ads-page .dgs-form-slot form {
  font-family: "Manrope", Arial, sans-serif !important;
  color: var(--dgs-text) !important;
  background: transparent !important;
  margin: 0 !important;
  padding: 0 !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-el-group {
  margin-bottom: 11px !important;
  color: var(--dgs-text) !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-el-input--label,
.dgs-seo-ads-page .dgs-form-slot .ff-el-input--label label,
.dgs-seo-ads-page .dgs-form-slot label,
.dgs-seo-ads-page .dgs-form-slot .ff-el-form-check-label {
  color: var(--dgs-text) !important;
  -webkit-text-fill-color: var(--dgs-text) !important;
  font-family: "Manrope", Arial, sans-serif !important;
  font-size: 14.5px !important;
  font-weight: 900 !important;
  line-height: 1.3 !important;
  margin-bottom: 7px !important;
  opacity: 1 !important;
  text-shadow: none !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-el-form-control,
.dgs-seo-ads-page .dgs-form-slot input[type="text"],
.dgs-seo-ads-page .dgs-form-slot input[type="email"],
.dgs-seo-ads-page .dgs-form-slot input[type="tel"],
.dgs-seo-ads-page .dgs-form-slot input[type="url"],
.dgs-seo-ads-page .dgs-form-slot input[type="number"],
.dgs-seo-ads-page .dgs-form-slot select,
.dgs-seo-ads-page .dgs-form-slot textarea {
  width: 100% !important;
  min-height: 48px !important;
  height: auto !important;
  border: 1px solid rgba(20,17,31,0.14) !important;
  border-radius: 13px !important;
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;
  color: var(--dgs-text) !important;
  -webkit-text-fill-color: var(--dgs-text) !important;
  box-shadow: none !important;
  outline: none !important;
  padding: 12px 15px !important;
  font-family: "Manrope", Arial, sans-serif !important;
  font-size: 15.5px !important;
  font-weight: 700 !important;
  line-height: 1.35 !important;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease !important;
}

.dgs-seo-ads-page .dgs-form-slot textarea {
  min-height: 82px !important;
  resize: vertical !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-el-form-control::placeholder,
.dgs-seo-ads-page .dgs-form-slot input::placeholder,
.dgs-seo-ads-page .dgs-form-slot textarea::placeholder {
  color: rgba(94,90,102,0.74) !important;
  -webkit-text-fill-color: rgba(94,90,102,0.74) !important;
  opacity: 1 !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-el-form-control:focus,
.dgs-seo-ads-page .dgs-form-slot input:focus,
.dgs-seo-ads-page .dgs-form-slot select:focus,
.dgs-seo-ads-page .dgs-form-slot textarea:focus {
  border-color: rgba(232,97,42,0.62) !important;
  box-shadow: 0 0 0 4px rgba(232,97,42,0.10) !important;
  background: #ffffff !important;
  color: var(--dgs-text) !important;
  -webkit-text-fill-color: var(--dgs-text) !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-el-form-check,
.dgs-seo-ads-page .dgs-form-slot .ff_t_c,
.dgs-seo-ads-page .dgs-form-slot .ff_tc_label {
  color: var(--dgs-text) !important;
  -webkit-text-fill-color: var(--dgs-text) !important;
  font-size: 12.5px !important;
  line-height: 1.5 !important;
}

.dgs-seo-ads-page .dgs-form-slot input[type="checkbox"],
.dgs-seo-ads-page .dgs-form-slot input[type="radio"] {
  width: 16px !important;
  height: 16px !important;
  min-height: 16px !important;
  accent-color: #e8612a !important;
  margin-top: 2px !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-el-form-check-label span,
.dgs-seo-ads-page .dgs-form-slot .ff_t_c span,
.dgs-seo-ads-page .dgs-form-slot .ff_t_c a {
  color: var(--dgs-text) !important;
  -webkit-text-fill-color: var(--dgs-text) !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-el-help-message,
.dgs-seo-ads-page .dgs-form-slot .ff-el-form-text,
.dgs-seo-ads-page .dgs-form-slot .ff-el-tooltip,
.dgs-seo-ads-page .dgs-form-slot .error,
.dgs-seo-ads-page .dgs-form-slot .ff-el-is-error .text-danger,
.dgs-seo-ads-page .dgs-form-slot .ff-el-is-error .error {
  color: #c43f7a !important;
  -webkit-text-fill-color: #c43f7a !important;
  font-size: 11.5px !important;
  line-height: 1.45 !important;
  margin-top: 5px !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-el-is-error .ff-el-form-control,
.dgs-seo-ads-page .dgs-form-slot .dgs-has-error .ff-el-form-control,
.dgs-seo-ads-page .dgs-form-slot .dgs-has-error input,
.dgs-seo-ads-page .dgs-form-slot .dgs-has-error textarea,
.dgs-seo-ads-page .dgs-form-slot .dgs-has-error select {
  border-color: #c43f7a !important;
  box-shadow: 0 0 0 4px rgba(196,63,122,0.10) !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-btn-submit,
.dgs-seo-ads-page .dgs-form-slot button[type="submit"],
.dgs-seo-ads-page .dgs-form-slot input[type="submit"] {
  width: 100% !important;
  min-height: 52px !important;
  border: 0 !important;
  border-radius: 999px !important;
  background: var(--dgs-gradient) !important;
  background-image: var(--dgs-gradient) !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  font-family: "Manrope", Arial, sans-serif !important;
  font-size: 15px !important;
  font-weight: 900 !important;
  letter-spacing: 0 !important;
  box-shadow: 0 18px 42px rgba(196,63,122,0.24) !important;
  cursor: pointer !important;
  transition: 0.28s ease !important;
  text-transform: none !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-btn-submit:hover,
.dgs-seo-ads-page .dgs-form-slot button[type="submit"]:hover,
.dgs-seo-ads-page .dgs-form-slot input[type="submit"]:hover {
  transform: translateY(-2px) !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  box-shadow: 0 24px 56px rgba(196,63,122,0.34) !important;
}

.dgs-seo-ads-page .dgs-form-slot .iti,
.dgs-seo-ads-page .dgs-form-slot .iti--allow-dropdown {
  width: 100% !important;
  color: var(--dgs-text) !important;
  background: #ffffff !important;
  background-image: none !important;
}

.dgs-seo-ads-page .dgs-form-slot .iti__flag-container,
.dgs-seo-ads-page .dgs-form-slot .iti__selected-flag,
.dgs-seo-ads-page .dgs-form-slot .iti__selected-flag:hover,
.dgs-seo-ads-page .dgs-form-slot .iti__selected-flag:focus {
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;
  box-shadow: none !important;
  border-radius: 13px 0 0 13px !important;
  border-right: 1px solid rgba(20,17,31,0.12) !important;
}

.dgs-seo-ads-page .dgs-form-slot .iti__selected-dial-code,
.dgs-seo-ads-page .dgs-form-slot .iti__arrow {
  color: var(--dgs-text) !important;
  -webkit-text-fill-color: var(--dgs-text) !important;
  background: transparent !important;
  background-image: none !important;
}

.dgs-seo-ads-page .dgs-form-slot .iti__country-list {
  background: #ffffff !important;
  color: var(--dgs-text) !important;
  border: 1px solid rgba(20,17,31,0.14) !important;
  box-shadow: 0 18px 44px rgba(20,17,31,0.16) !important;
}

.dgs-seo-ads-page .dgs-form-slot .iti__country,
.dgs-seo-ads-page .dgs-form-slot .iti__dial-code {
  color: var(--dgs-text) !important;
  -webkit-text-fill-color: var(--dgs-text) !important;
}

/* Fluent Forms phone country selector fix. This kills theme gradients and keeps the dial code visible. */
.dgs-seo-ads-page .dgs-form-slot .iti,
.dgs-seo-ads-page .dgs-form-slot .iti--allow-dropdown,
.dgs-seo-ads-page .dgs-form-slot .iti--separate-dial-code {
  width: 100% !important;
  color: var(--dgs-text) !important;
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;
  border-radius: 13px !important;
}

.dgs-seo-ads-page .dgs-form-slot .iti input,
.dgs-seo-ads-page .dgs-form-slot .iti input[type="tel"],
.dgs-seo-ads-page .dgs-form-slot input.iti__tel-input,
.dgs-seo-ads-page .dgs-form-slot .ff-el-phone input,
.dgs-seo-ads-page .dgs-form-slot .ff-el-phone .ff-el-form-control {
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;
  color: var(--dgs-text) !important;
  -webkit-text-fill-color: var(--dgs-text) !important;
  font-size: 15.5px !important;
  font-weight: 750 !important;
  min-height: 48px !important;
  padding-top: 12px !important;
  padding-bottom: 12px !important;
}

.dgs-seo-ads-page .dgs-form-slot .iti--allow-dropdown input,
.dgs-seo-ads-page .dgs-form-slot .iti--separate-dial-code input,
.dgs-seo-ads-page .dgs-form-slot input.iti__tel-input {
  padding-left: 112px !important;
}

