/* DARK CASE STUDY POPUP */
.dgs-modal-overlay {
  position: fixed !important;
  inset: 0 !important;
  background: rgba(8, 7, 13, 0.82) !important;
  backdrop-filter: blur(18px) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  z-index: 999999 !important;
  padding: 24px !important;
  opacity: 0 !important;
  visibility: hidden !important;
  transition: 0.34s ease !important;
}

.dgs-modal-overlay.active {
  opacity: 1 !important;
  visibility: visible !important;
}

.dgs-modal-box {
  background: #111019 !important;
  border: 1px solid rgba(255,255,255,0.12) !important;
  color: #ffffff !important;
  border-radius: var(--dgs-radius-lg) !important;
  max-width: 760px !important;
  width: 100% !important;
  max-height: 88vh !important;
  overflow-y: auto !important;
  position: relative !important;
  box-shadow: 0 44px 130px rgba(0,0,0,0.55) !important;
  transform: translateY(24px) scale(0.97) !important;
  transition: 0.34s ease !important;
}

.dgs-modal-overlay.active .dgs-modal-box {
  transform: translateY(0) scale(1) !important;
}

.dgs-modal-head {
  position: sticky !important;
  top: 0 !important;
  background:
    radial-gradient(circle at 10% 0%, rgba(232,97,42,0.16), transparent 34%),
    radial-gradient(circle at 90% 10%, rgba(98,71,176,0.18), transparent 36%),
    #111019 !important;
  backdrop-filter: blur(16px) !important;
  padding: 32px 72px 28px 36px !important;
  border-bottom: 1px solid rgba(255,255,255,0.10) !important;
  z-index: 10 !important;
}

.dgs-modal-head:before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: 4px !important;
  background: var(--dgs-gradient) !important;
  border-radius: var(--dgs-radius-lg) var(--dgs-radius-lg) 0 0 !important;
}

.dgs-modal-close,
button.dgs-modal-close {
  position: absolute !important;
  top: 20px !important;
  right: 20px !important;
  width: 40px !important;
  height: 40px !important;
  border-radius: 50% !important;
  background: rgba(255,255,255,0.08) !important;
  background-image: none !important;
  border: 1px solid rgba(255,255,255,0.16) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer !important;
  color: #ffffff !important;
  padding: 0 !important;
  margin: 0 !important;
  box-shadow: none !important;
}

.dgs-modal-close:hover {
  background: rgba(232,97,42,0.12) !important;
  border-color: rgba(232,97,42,0.55) !important;
  color: #e8612a !important;
  transform: scale(1.08) !important;
}

.dgs-modal-close svg {
  width: 17px !important;
  height: 17px !important;
  stroke: currentColor !important;
  fill: none !important;
  stroke-width: 2 !important;
}

.dgs-modal-logo {
  background: #ffffff !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: auto !important;
  min-height: 54px !important;
  padding: 10px 14px !important;
  border-radius: 14px !important;
