}

.dgs-modal-section:last-child {
  margin-bottom: 0 !important;
}

.dgs-modal-section-title {
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
  font-size: 20px !important;
  font-weight: 950 !important;
  color: #ffffff !important;
