    box-shadow: 0 18px 54px rgba(20,17,31,0.28) !important;
  }

  .dgs-modal-head {
    padding: 24px 64px 22px 22px !important;
  }

  .dgs-modal-body {
    padding: 22px !important;
  }

  .dgs-modal-img {
