/* FINAL PHONE FIELD FIX V6
   Do not create fake dial-code text. Do not let theme gradients touch the phone selector.
   Keep the country selector visible as a small white control and keep the typed number readable. */
.dgs-seo-ads-page .dgs-form-slot .ff-el-phone,
.dgs-seo-ads-page .dgs-form-slot .ff-el-phone *,
.dgs-seo-ads-page .dgs-form-slot .iti,
.dgs-seo-ads-page .dgs-form-slot .iti *,
.dgs-seo-ads-page .dgs-form-slot .iti--allow-dropdown,
.dgs-seo-ads-page .dgs-form-slot .iti--separate-dial-code {
  box-sizing: border-box !important;
  text-shadow: none !important;
}

.dgs-seo-ads-page .dgs-form-slot .ff-el-phone .ff-el-input--content,
.dgs-seo-ads-page .dgs-form-slot .iti,
.dgs-seo-ads-page .dgs-form-slot .iti--allow-dropdown,
.dgs-seo-ads-page .dgs-form-slot .iti--separate-dial-code {
  width: 100% !important;
  position: relative !important;
  display: block !important;
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;
  border: 0 !important;
  border-radius: 14px !important;
  color: #14111f !important;
  -webkit-text-fill-color: #14111f !important;
  overflow: visible !important;
}

/* Kill theme gradient on every visible country selector layer */
.dgs-seo-ads-page .dgs-form-slot .ff-el-phone .iti__country-container,
.dgs-seo-ads-page .dgs-form-slot .ff-el-phone .iti__flag-container,
.dgs-seo-ads-page .dgs-form-slot .ff-el-phone .iti__selected-country,
.dgs-seo-ads-page .dgs-form-slot .ff-el-phone button.iti__selected-country,
.dgs-seo-ads-page .dgs-form-slot .ff-el-phone .iti__selected-flag,
.dgs-seo-ads-page .dgs-form-slot .ff-el-phone .iti__selected-country-primary,
.dgs-seo-ads-page .dgs-form-slot .iti__country-container,
.dgs-seo-ads-page .dgs-form-slot .iti__flag-container,
.dgs-seo-ads-page .dgs-form-slot .iti__selected-country,
.dgs-seo-ads-page .dgs-form-slot button.iti__selected-country,
.dgs-seo-ads-page .dgs-form-slot .iti__selected-flag,
.dgs-seo-ads-page .dgs-form-slot .iti__selected-country-primary {
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;
  background-clip: border-box !important;
  filter: none !important;
  box-shadow: none !important;
  border: 0 !important;
  outline: 0 !important;
  color: #14111f !important;
  -webkit-text-fill-color: #14111f !important;
}

.dgs-seo-ads-page .dgs-form-slot .iti__country-container,
.dgs-seo-ads-page .dgs-form-slot .iti__flag-container {
  position: absolute !important;
  left: 1px !important;
  top: 1px !important;
  bottom: 1px !important;
  width: 70px !important;
  min-width: 70px !important;
  max-width: 70px !important;
  height: calc(100% - 2px) !important;
  z-index: 4 !important;
  border-right: 1px solid rgba(20,17,31,0.14) !important;
  border-radius: 13px 0 0 13px !important;
  overflow: hidden !important;
}

.dgs-seo-ads-page .dgs-form-slot .iti__selected-country,
.dgs-seo-ads-page .dgs-form-slot button.iti__selected-country,
.dgs-seo-ads-page .dgs-form-slot .iti__selected-flag {
  width: 70px !important;
  min-width: 70px !important;
  max-width: 70px !important;
  height: 100% !important;
  min-height: 50px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 6px !important;
  padding: 0 9px !important;
  margin: 0 !important;
  border-radius: 13px 0 0 13px !important;
}

/* Hide dial-code text in the selector. This prevents the +91 overlay problem.
   The phone plugin can still submit the selected country internally. */
.dgs-seo-ads-page .dgs-form-slot .iti__selected-dial-code,
.dgs-seo-ads-page .dgs-form-slot .dgs-visible-dial-code {
  display: none !important;
  visibility: hidden !important;
  width: 0 !important;
  max-width: 0 !important;
